-- Optymistyczny zapis "ręcznie"
UPDATE Products
SET Price = @newPrice
WHERE Id = @id AND RowVer = @originalRowVer;

IF @@ROWCOUNT = 0
    THROW 50001, 'Konflikt: ktoś zmienił produkt w międzyczasie.', 1;

public class Product
{
    public int Id { get; set; }
    public decimal Price { get; set; }
    [Timestamp] public byte[] RowVersion { get; set; } = [];
}

var p = await db.Products.FindAsync(id);          // 1
p!.Price = dto.Price;                             // 2
db.Entry(p).Property(x => x.RowVersion).OriginalValue = dto.RowVersion;
try { await db.SaveChangesAsync(); }              // 3
catch (DbUpdateConcurrencyException)              // 4
{
    return Results.Conflict("Produkt został zmieniony przez kogoś innego."); // 5
}

// ŹLE: singleton trzyma jeden DbContext przez cały czas życia aplikacji
public class Worker(AppDbContext db) : BackgroundService { /* ... */ }

// DOBRZE: krótko żyjący kontekst na każdą porcję pracy
public class Worker(IDbContextFactory<AppDbContext> factory) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        await using var db = await factory.CreateDbContextAsync(ct);
        // ... praca, SaveChangesAsync, kontekst znika
    }
}

// ŹLE: 1 + N zapytań (przy lazy loading)
var orders = await db.Orders.ToListAsync();
foreach (var o in orders)
    Console.WriteLine(o.Customer.Name);   // osobne zapytanie za każdym razem

// DOBRZE: 1 zapytanie z JOIN, tylko potrzebne kolumny
var rows = await db.Orders
    .Select(o => new { o.Id, CustomerName = o.Customer.Name })
    .ToListAsync();

